import {products} from './data.js';
const key='morkov.selection.v1';
const format=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);
const byId=id=>products.find(p=>p.id===id);
let selection={};
try{const raw=JSON.parse(localStorage.getItem(key)||'{}');if(raw&&typeof raw==='object'&&!Array.isArray(raw)){for(const p of products){const n=Number(raw[p.id]);if(Number.isFinite(n)&&n>0)selection[p.id]=Math.min(99,Math.max(p.step,Math.round(n/p.step)*p.step));}}}catch{}
const toast=document.querySelector('.toast');let toastTimer;
function notify(message){const active=document.querySelector('dialog[open] .dialog-status');if(active){active.textContent=message;return}toast.textContent=message;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3200)}
function save(){try{localStorage.setItem(key,JSON.stringify(selection))}catch{notify('Список сохранён только на время этой страницы.')}updateBadge()}
function updateBadge(){document.querySelectorAll('.selection-count').forEach(el=>{el.textContent=Object.keys(selection).length;el.setAttribute('aria-label',`Позиций в списке: ${Object.keys(selection).length}`)})}
const escapeHTML=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function inquiry(){return 'Здравствуйте! Подскажите, пожалуйста, наличие и стоимость:\n'+Object.entries(selection).map(([id,n])=>`${byId(id).name} — ${format(n)} ${byId(id).unit}`).join('\n')+'\nСпасибо!'}
function renderSelection(){const entries=Object.entries(selection);const target=document.getElementById('selection-items');document.getElementById('inquiry-panel').hidden=entries.length===0;if(!entries.length){target.innerHTML='<div class="selection-empty"><h3>Здесь будет<br>что-нибудь вкусное.</h3><p>Добавляйте продукты из каталога. Ваш список останется в браузере до следующего визита.</p><a class="button primary" href="catalog.html">Выбрать продукты</a></div>';return}target.innerHTML=entries.map(([id,n])=>{const p=byId(id);return `<div class="selection-row" data-row="${id}"><a href="product-${id}.html" aria-label="${escapeHTML(p.name)}: подробнее"><div class="product-photo p${p.photo}" role="img" aria-label="${escapeHTML(p.name)}"></div></a><div class="selection-row-content"><div><h3>${escapeHTML(p.name)}</h3><button class="remove-item" data-remove="${id}" aria-label="Удалить ${escapeHTML(p.name)}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="quantity"><button data-change="${id}" data-delta="-1" aria-label="Уменьшить количество: ${escapeHTML(p.name)}" ${n<=p.step?'disabled':''}>−</button><output aria-live="polite">${format(n)} ${p.unit}</output><button data-change="${id}" data-delta="1" aria-label="Увеличить количество: ${escapeHTML(p.name)}" ${n+p.step>99?'disabled':''}>+</button></div></div></div>`}).join('');document.getElementById('inquiry-text').value=inquiry()}
let lastOpener=null;
function openDialog(id,opener){document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(id==='selection')renderSelection();const dialog=document.getElementById(id);lastOpener=opener;document.body.classList.add('dialog-open');document.documentElement.setAttribute('data-lenis-prevent','');dialog.showModal()}
document.querySelector('.selection-trigger').addEventListener('click',e=>openDialog('selection',e.currentTarget));
document.querySelector('.menu-trigger').addEventListener('click',e=>openDialog('mobile-menu',e.currentTarget));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('[data-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')){document.body.classList.remove('dialog-open');document.documentElement.removeAttribute('data-lenis-prevent')}lastOpener?.focus()});dialog.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>dialog.close()))});
let detailAmount=Number(document.querySelector('.quantity[data-step]')?.dataset.step)||1;
const detailQuantity=document.querySelector('.quantity[data-step]');
if(detailQuantity){const step=Number(detailQuantity.dataset.step);const output=detailQuantity.querySelector('output');const refresh=()=>{output.textContent=`${format(detailAmount)} ${detailQuantity.dataset.unit}`;detailQuantity.querySelector('[data-quantity="minus"]').disabled=detailAmount<=step;detailQuantity.querySelector('[data-quantity="plus"]').disabled=detailAmount+step>99};detailQuantity.querySelectorAll('[data-quantity]').forEach(button=>button.addEventListener('click',()=>{detailAmount=Math.min(99,Math.max(step,detailAmount+(button.dataset.quantity==='plus'?step:-step)));refresh()}));refresh()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const p=byId(add.dataset.add);if(!p)return;const n=add.dataset.detail?detailAmount:p.step;selection[p.id]=Math.min(99,(selection[p.id]||0)+n);save();notify(`${p.name}: в вашем списке`);add.animate?.([{transform:'scale(.94)'},{transform:'scale(1)'}],{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:220,easing:'ease-out'})}const remove=e.target.closest('[data-remove]');if(remove){delete selection[remove.dataset.remove];save();renderSelection();document.querySelector(`[data-remove="${Object.keys(selection)[0]}"]`)?.focus();if(!Object.keys(selection).length)document.querySelector('#selection [data-close]').focus()}const change=e.target.closest('[data-change]');if(change){const id=change.dataset.change;const p=byId(id);selection[id]=Math.max(p.step,Math.min(99,selection[id]+Number(change.dataset.delta)*p.step));const delta=change.dataset.delta;save();renderSelection();const same=document.querySelector(`[data-change="${id}"][data-delta="${delta}"]`);if(same&&!same.disabled)same.focus();else document.querySelector(`[data-change="${id}"]:not(:disabled)`)?.focus()}});
document.getElementById('copy-inquiry').addEventListener('click',async()=>{const text=document.getElementById('inquiry-text');try{await navigator.clipboard.writeText(text.value);notify('Список скопирован. Можно обсудить покупку с магазином.')}catch{text.focus();text.select();notify('Выделили список. Скопируйте его вручную.')}});
window.addEventListener('storage',e=>{if(e.key===key){try{const raw=JSON.parse(e.newValue||'{}');selection={};for(const p of products){const n=Number(raw?.[p.id]);if(Number.isFinite(n)&&n>0)selection[p.id]=Math.min(99,Math.max(p.step,Math.round(n/p.step)*p.step))}updateBadge();if(document.getElementById('selection').open)renderSelection()}catch{}}});
updateBadge();
const search=document.getElementById('catalog-search');
if(search){const norm=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').trim();const params=new URLSearchParams(location.search);let category=['all','fruits','berries','drinks'].includes(params.get('category'))?params.get('category'):'all';search.value=(params.get('q')||'').slice(0,80);const buttons=[...document.querySelectorAll('[data-filter]')];const cards=[...document.querySelectorAll('#catalog-grid .product-card')];function filter(){const q=norm(search.value);let count=0;cards.forEach(card=>{const visible=(category==='all'||card.dataset.category===category)&&norm(card.dataset.name).includes(q);card.hidden=!visible;if(visible)count++});buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));document.getElementById('result-count').textContent=`${count} ${count===1?'продукт':count>=2&&count<=4?'продукта':'продуктов'}`;document.getElementById('catalog-empty').hidden=count>0;const next=new URL(location.href);if(category!=='all')next.searchParams.set('category',category);else next.searchParams.delete('category');if(search.value)next.searchParams.set('q',search.value);else next.searchParams.delete('q');history.replaceState(null,'',next)}buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filter()}));search.addEventListener('input',filter);document.getElementById('reset-filters').addEventListener('click',()=>{category='all';search.value='';filter();search.focus()});filter()}
let effects;
const media=matchMedia('(min-width: 768px) and (pointer: fine)');
function parallaxAttributes(){document.querySelectorAll('[data-desktop-parallax]').forEach(el=>{if(media.matches)el.dataset.parallax=el.dataset.desktopParallax;else el.removeAttribute('data-parallax')})}
async function mount(){parallaxAttributes();const {mountEffects}=await import('../site-effects/runtime.js');effects=mountEffects(document,{enabled:media.matches,onError:error=>console.warn('[Motion]',error.message)});await effects.ready}
mount().catch(error=>console.warn('[Motion]',error.message));
media.addEventListener('change',()=>{effects?.destroy();mount()});
window.addEventListener('pagehide',()=>effects?.destroy());
window.addEventListener('pageshow',event=>{if(event.persisted){try{const raw=JSON.parse(localStorage.getItem(key)||'{}');selection={};for(const p of products){const n=Number(raw?.[p.id]);if(Number.isFinite(n)&&n>0)selection[p.id]=Math.min(99,Math.max(p.step,Math.round(n/p.step)*p.step))}updateBadge()}catch{}mount()}});
